package certify

import (
	"context"
	"crypto/ed25519"
	"crypto/rand"
	"encoding/json"
	"testing"

	"github.com/secure-systems-lab/go-securesystemslib/dsse"
)

func TestVerifyDSSEInvalidJSONPayloadFails(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}

	sv := &ed25519SigVerifier{priv: priv, keyID: "corral-test"}
	es, err := dsse.NewEnvelopeSigner(sv)
	if err != nil {
		t.Fatalf("NewEnvelopeSigner: %v", err)
	}

	invalidPayload := []byte("{this is not valid json")
	env, err := es.SignPayload(context.Background(), intotoPayloadType, invalidPayload)
	if err != nil {
		t.Fatalf("SignPayload: %v", err)
	}

	envelopeBytes, err := json.Marshal(env)
	if err != nil {
		t.Fatalf("json.Marshal envelope: %v", err)
	}

	_, ok, err := VerifyDSSE(envelopeBytes, pub)
	if err != nil {
		t.Fatalf("VerifyDSSE unexpected error: %v", err)
	}
	if ok {
		t.Fatal("VerifyDSSE must return ok=false when envelope payload is not valid JSON")
	}
}

