package certify

import (
	"crypto/ed25519"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"testing"
)

func TestDSSESignKeyIDAndTamperEvidence(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("GenerateKey error: %v", err)
	}

	steps := []Step{
		{Kind: "execution", Subject: "go test ./..."},
	}
	_, head := BuildLedger(steps)

	record := BuildRecord{
		Repo:       "github.com/example/repo",
		Commit:     "1234567890abcdef",
		Command:    "go test ./...",
		ExitCode:   0,
		ProducedBy: []string{"claude-3-5-sonnet"},
	}

	stmt := BuildAttestation(record, head)

	expectedKeyID := "corral-signer-key-1"
	envBytes, err := SignDSSE(stmt, priv, expectedKeyID)
	if err != nil {
		t.Fatalf("SignDSSE returned unexpected error: %v", err)
	}

	var envStruct struct {
		Signatures []struct {
			KeyID string `json:"keyid"`
		} `json:"signatures"`
	}
	if err := json.Unmarshal(envBytes, &envStruct); err != nil {
		t.Fatalf("Unmarshal envelope error: %v", err)
	}

	if len(envStruct.Signatures) == 0 {
		t.Fatalf("DSSE envelope has no signatures")
	}

	if gotKeyID := envStruct.Signatures[0].KeyID; gotKeyID != expectedKeyID {
		t.Fatalf("SignDSSE keyID = %q, want %q", gotKeyID, expectedKeyID)
	}

	_, ok, err := VerifyDSSE(envBytes, pub)
	if err != nil {
		t.Fatalf("VerifyDSSE returned error: %v", err)
	}
	if !ok {
		t.Fatalf("VerifyDSSE failed for untampered envelope")
	}

	var envMap map[string]any
	if err := json.Unmarshal(envBytes, &envMap); err != nil {
		t.Fatalf("json.Unmarshal error: %v", err)
	}

	payloadB64, ok := envMap["payload"].(string)
	if !ok {
		t.Fatalf("payload missing or not string")
	}

	rawPayload, err := base64.StdEncoding.DecodeString(payloadB64)
	if err != nil {
		t.Fatalf("base64 decode error: %v", err)
	}

	var payloadStmt map[string]any
	if err := json.Unmarshal(rawPayload, &payloadStmt); err != nil {
		t.Fatalf("unmarshal payload error: %v", err)
	}

	payloadStmt["predicate"].(map[string]any)["runDetails"].(map[string]any)["byproducts"].([]any)[1].(map[string]any)["annotations"].(map[string]any)["exitCode"] = 1

	tamperedPayloadBytes, err := json.Marshal(payloadStmt)
	if err != nil {
		t.Fatalf("marshal tampered payload error: %v", err)
	}

	envMap["payload"] = base64.StdEncoding.EncodeToString(tamperedPayloadBytes)
	tamperedEnvBytes, err := json.Marshal(envMap)
	if err != nil {
		t.Fatalf("marshal tampered envelope error: %v", err)
	}

	if _, ok, _ := VerifyDSSE(tamperedEnvBytes, pub); ok {
		t.Fatalf("VerifyDSSE succeeded on tampered verdict payload")
	}
}

