func TestVerifyDSSE_UnpaddedPayloadFails(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("GenerateKey failed: %v", err)
	}

	_, head := BuildLedger([]Step{{Kind: "execution", Subject: "go build"}})
	stmt := BuildAttestation(BuildRecord{
		Repo: "r", Commit: "c", Command: "go build", ExitCode: 0,
		ProducedBy: []string{"anthropic:claude-opus"},
	}, head)

	envBytes, err := SignDSSE(stmt, priv, "key1")
	if err != nil {
		t.Fatalf("SignDSSE failed: %v", err)
	}

	var envMap map[string]any
	if err := json.Unmarshal(envBytes, &envMap); err != nil {
		t.Fatalf("json.Unmarshal envelope failed: %v", err)
	}

	payloadStr, ok := envMap["payload"].(string)
	if !ok || payloadStr == "" {
		t.Fatalf("invalid payload in envelope: %v", envMap)
	}

	// Convert payload to unpadded URL-safe base64.
	// Trimming '=' causes standard base64.URLEncoding.DecodeString to return an error.
	unpaddedPayload := strings.ReplaceAll(payloadStr, "+", "-")
	unpaddedPayload = strings.ReplaceAll(unpaddedPayload, "/", "_")
	unpaddedPayload = strings.TrimRight(unpaddedPayload, "=")

	envMap["payload"] = unpaddedPayload
	tamperedEnv, err := json.Marshal(envMap)
	if err != nil {
		t.Fatalf("json.Marshal tampered envelope failed: %v", err)
	}

	if _, ok, _ := VerifyDSSE(tamperedEnv, pub); ok {
		t.Fatal("VerifyDSSE must fail when base64 payload decoding fails (e.g. unpadded URL payload)")
	}
}

