	}

	for i, key := range invalidKeys {
		err := func() (err error) {
			defer func() {
				if r := recover(); r != nil {
					t.Fatalf("key index %d: SignDSSE panicked with %v; expected error response", i, r)
				}
			}()
			_, err = SignDSSE(stmt, key, "key-id")
			return err
		}()

		if err == nil {
			t.Fatalf("key index %d: SignDSSE should have returned error for invalid private key length", i)
		}
	}
}

func TestDSSETamperEvidentStatement(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("GenerateKey error: %v", err)
	}

	record := BuildRecord{
		Repo:       "myrepo",
		Commit:     "1234567890abcdef",
		Command:    "go test ./...",
		ExitCode:   0,
		ProducedBy: []string{"anthropic:claude-3-5-sonnet"},
	}
	head := "11223344556677889900aabbccddeeff11223344556677889900aabbccddeeff"

	stmt := BuildAttestation(record, head)
	env, err := SignDSSE(stmt, priv, "key1")
	if err != nil {
		t.Fatalf("SignDSSE error: %v", err)
	}

	tamperPayload := func(modFn func(stmtMap map[string]any)) []byte {
		var envMap map[string]any
		if err := json.Unmarshal(env, &envMap); err != nil {
			t.Fatalf("unmarshal env: %v", err)
		}
		payloadB64, ok := envMap["payload"].(string)
		if !ok {
			t.Fatal("missing payload string in envelope")
		}
		rawPayload, err := base64.StdEncoding.DecodeString(payloadB64)
		if err != nil {
			t.Fatalf("base64 decode: %v", err)
		}
		var st map[string]any
		if err := json.Unmarshal(rawPayload, &st); err != nil {
			t.Fatalf("unmarshal payload: %v", err)
		}
		modFn(st)
		newPayload, err := json.Marshal(st)
		if err != nil {
			t.Fatalf("marshal payload: %v", err)
		}
		envMap["payload"] = base64.StdEncoding.EncodeToString(newPayload)
		res, err := json.Marshal(envMap)
		if err != nil {
			t.Fatalf("marshal env: %v", err)
		}
		return res
	}

	// 1. Tamper with model names
	tamperedModel := tamperPayload(func(st map[string]any) {
		pred := st["predicate"].(map[string]any)
		bdef := pred["buildDefinition"].(map[string]any)
		bdef["resolvedDependencies"] = []any{
			map[string]any{"uri": "model:malicious-model"},
		}
	})
	if _, ok, _ := VerifyDSSE(tamperedModel, pub); ok {
		t.Fatal("VerifyDSSE must fail when model names are tampered")
	}

	// 2. Tamper with subject hashes
	tamperedSubject := tamperPayload(func(st map[string]any) {
		subj := st["subject"].([]any)
		s0 := subj[0].(map[string]any)
		s0["digest"] = map[string]any{"sha256": "ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"}
	})
	if _, ok, _ := VerifyDSSE(tamperedSubject, pub); ok {
		t.Fatal("VerifyDSSE must fail when subject digest is tampered")
	}

	// 3. Tamper with verdict (exitCode/passed)
	tamperedVerdict := tamperPayload(func(st map[string]any) {
		pred := st["predicate"].(map[string]any)
		rd := pred["runDetails"].(map[string]any)
		byprods := rd["byproducts"].([]any)
		b1 := byprods[1].(map[string]any)
		ann := b1["annotations"].(map[string]any)
		ann["exitCode"] = float64(1)
		ann["passed"] = false
	})
	if _, ok, _ := VerifyDSSE(tamperedVerdict, pub); ok {
		t.Fatal("VerifyDSSE must fail when verdict/exitCode is tampered")
	}
}

