package certify

import (
	"crypto/ed25519"
	"crypto/rand"
	"encoding/json"
	"strings"
	"testing"
)

func TestVerifyDSSE_UnpaddedBase64PayloadFails(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("GenerateKey failed: %v", err)
	}

	_, head := BuildLedger([]Step{{Kind: "execution", Subject: "go build"}})

	repo := "r"
	var envBytes []byte
	var payloadStr string

	// Ensure the generated base64 payload requires padding '=' so that stripping it
	// forces base64.URLEncoding.DecodeString to return a decoding error.
	for {
		stmt := BuildAttestation(BuildRecord{
			Repo: repo, Commit: "c", Command: "go build", ExitCode: 0,
			ProducedBy: []string{"anthropic:claude-opus"},
		}, head)

		envBytes, err = SignDSSE(stmt, priv, "key1")
		if err != nil {
			t.Fatalf("SignDSSE failed: %v", err)
		}

		var envMap map[string]any
		if err := json.Unmarshal(envBytes, &envMap); err != nil {
			t.Fatalf("json.Unmarshal failed: %v", err)
		}

		var ok bool
		payloadStr, ok = envMap["payload"].(string)
		if !ok || payloadStr == "" {
			t.Fatalf("invalid payload string in DSSE envelope: %v", envMap)
		}

		if strings.HasSuffix(payloadStr, "=") {
			break
		}
		repo += "x"
	}

	var envMap map[string]any
	if err := json.Unmarshal(envBytes, &envMap); err != nil {
		t.Fatalf("json.Unmarshal failed: %v", err)
	}

	// Strip padding so base64 decoding fails in both StdEncoding and URLEncoding.
	unpaddedPayload := strings.TrimRight(strings.ReplaceAll(strings.ReplaceAll(payloadStr, "+", "-"), "/", "_"), "=")
	envMap["payload"] = unpaddedPayload

	tamperedEnv, err := json.Marshal(envMap)
	if err != nil {
		t.Fatalf("json.Marshal failed: %v", err)
	}

	_, ok, err := VerifyDSSE(tamperedEnv, pub)
	if err != nil {
		t.Fatalf("VerifyDSSE returned unexpected error: %v", err)
	}
	if ok {
		t.Fatal("VerifyDSSE must fail (ok=false) when envelope payload uses unpadded base64")
	}
}
